-- ─────────────────────────────────────────────────────────────────────────────
-- JCCS Projects — the office's first estimate lessons (2026-11-03)
-- Run once, by hand, AFTER 2026-11-03d_library_scopes.sql. Additive; re-running
-- updates the wording. Written from JCCS's past estimates; too-general crew
-- words (door, frame, tile, countertop on laminate…) left out so a lesson only
-- fires on its own work. Edit any of them in Materials Library afterwards.
-- ─────────────────────────────────────────────────────────────────────────────

INSERT INTO quote_library (kind, label, aliases, unit, scope_text, checks) VALUES
  ('laminate', 'Cabinet installation', 'cabinets, cabinetry, millwork, upper cabinets, lower cabinets, base cabinets, wall cabinets, gabinetes, gabinetes de arriba, gabinetes de abajo', 'LF',
   '# Cabinet Installation\nFabricate and install {amount}upper and lower cabinets {where}.\nProvide the approved cabinet material, laminate, color, style, and finish.\nProvide doors, drawers, adjustable shelves, hinges, pulls, slides, finished panels, fillers, toe kicks, and associated hardware as applicable.\nProvide blocking, anchors, fasteners, supports, and reinforcement as required.\nLevel, align, and securely fasten the cabinets to the supporting structure.',
   'Verify the cabinets are level, properly aligned, securely fastened, and structurally supported.\nVerify cabinet doors, drawers, shelves, hinges, and hardware function as intended.'),
  ('solid_surface', 'Solid-surface countertop', 'solid surface, Corian, countertop, counter, encimera, mostrador, superficie sólida', 'LF',
   '# Solid-Surface Countertop Installation\nFabricate and install {amount}solid-surface countertop {where}.\nProvide the approved material, color, finish, thickness, and edge profile.\nProvide required finished edges, seams, cutouts, supports, and reinforcement.\nLevel, align, and securely fasten the countertop to the supporting cabinets or support system.\nSeal countertop joints, edges, seams, and wall transitions as required.\nComplete fabrication and installation according to field-verified dimensions and manufacturer recommendations.',
   'Verify the countertop is level, properly aligned, securely fastened, and adequately supported.\nVerify seams, edges, cutouts, and wall transitions have a clean, uniform appearance.'),
  ('laminate', 'Laminate countertop', 'laminate countertop, laminate counter, Formica, encimera laminada, mostrador laminado', 'LF',
   '# Laminate Countertop Installation\nFabricate and install {amount}laminate countertop {where}.\nProvide the approved laminate color, pattern, finish, thickness, and edge treatment.\nProvide required finished edges, seams, cutouts, supports, and reinforcement.\nLevel, align, and securely fasten the countertop to the supporting cabinets or structure.\nSeal countertop joints, edges, seams, and wall transitions as required.',
   'Verify the countertop is level, properly aligned, securely fastened, and adequately supported.\nVerify the laminate surfaces, finished edges, seams, and cutouts have a clean, uniform appearance.'),
  ('other', 'Door and frame', 'door and frame, metal door, wood door, hollow metal, HM door, puerta y marco, new door, puerta nueva', 'EA',
   '# Door & Frame Installation\nProvide and install {amount}door and compatible frame {where}.\nCoordinate the door type, frame depth, finish, handing, swing, and hardware preparation with the approved project specifications.\nSet, level, align, anchor, and securely fasten the frame within the prepared opening.\nInstall compatible hinges, lockset or latchset, closer, stop, fasteners, and associated hardware as applicable.\nApply compatible sealant around the frame perimeter and adjacent transitions as required.\nAdjust the door and hardware to provide proper clearances and smooth operation.',
   'Verify the door and frame are plumb, level, properly aligned, securely fastened, and stable.\nVerify the door opens, closes, latches, and clears the frame and flooring properly.\nVerify the installed hardware functions smoothly and as intended.'),
  ('flooring', 'Carpet', 'carpet, broadloom carpet, carpet roll, wall-to-wall carpet, alfombra, piso de alfombra', 'SF',
   '# Subfloor Preparation\nRemove residual adhesive, loose materials, and surface contaminants as required.\nPatch and level minor substrate imperfections to provide a suitable installation surface.\n# Carpet Installation\nProvide and install {amount}carpet {where}.\nProvide compatible adhesive, tack strips, cushion, transitions, and installation materials as applicable.\nCut and fit the carpet neatly around walls, corners, door frames, and fixed components.\nComplete seams and transitions according to manufacturer recommendations.',
   'Verify the carpet is securely installed, properly stretched, and free of wrinkles, bubbles, or loose edges.\nVerify seams, perimeter cuts, and transitions have a clean, uniform appearance.'),
  ('flooring', 'Carpet tile', 'carpet tile, carpet squares, modular carpet, alfombra modular, losetas de alfombra, cuadros de alfombra', 'SF',
   '# Subfloor Preparation\nRemove residual adhesive, loose materials, and surface contaminants as required.\nPatch and level minor substrate imperfections to provide a suitable installation surface.\n# Carpet Tile Installation\nProvide and install {amount}carpet tile {where}.\nInstall the approved pattern and directional layout using compatible adhesive.\nCut and fit the carpet tile neatly around walls, corners, door frames, and fixed components.\nProvide required transition strips and perimeter finishes.',
   'Verify all carpet tiles are securely adhered, properly aligned, and free of raised or loose edges.\nVerify the pattern, seams, perimeter cuts, and transitions have a consistent appearance.'),
  ('flooring', 'Sheet vinyl flooring', 'sheet vinyl, roll vinyl, vinyl roll, welded flooring, heat-welded vinyl, piso de vinilo, vinilo en rollo, piso soldado', 'SF',
   '# Subfloor Preparation\nRemove residual adhesive, loose materials, and surface contaminants as required.\nPatch, smooth, and level the substrate to provide a suitable installation surface.\n# Sheet Vinyl Flooring Installation\nProvide and install {amount}sheet vinyl flooring {where}.\nInstall the flooring using compatible adhesive and installation materials per manufacturer recommendations.\nCut and fit the flooring neatly around walls, corners, door frames, penetrations, and fixed components.\nHeat-weld seams and complete transitions as required for a continuous finished surface.',
   'Verify the flooring is fully adhered, properly aligned, and free of bubbles, loose edges, or immediate tripping hazards.\nVerify welded seams, perimeter cuts, and transitions are smooth, secure, and uniform.'),
  ('flooring', 'Ceramic floor tile', 'ceramic tile, floor tile, bathroom tile, loseta, baldosa, cerámica, piso de cerámica', 'SF',
   '# Substrate Preparation\nClean and prepare the substrate to receive the new tile.\nPatch and level minor substrate imperfections as required.\n# Ceramic Tile Installation\nProvide and install {amount}ceramic floor tile {where}.\nInstall the tile using compatible setting materials according to the approved layout.\nCut and fit the tile neatly around walls, corners, door frames, fixtures, and penetrations.\nGrout the tile joints using the approved color and clean the completed surfaces.',
   'Verify the tiles are securely installed, properly aligned, and free of loose or uneven sections.\nVerify grout joints, perimeter cuts, and transitions have a clean, consistent appearance.'),
  ('flooring', 'Terrazzo repair', 'terrazzo, terrazzo repair, patch terrazzo, terrazo, reparar terrazo, parche de terrazo', 'SF',
   '# Terrazzo Flooring Repair\nRepair {amount}terrazzo flooring {where}.\nRemove loose, cracked, or deteriorated material within the affected sections as required.\nClean and prepare the exposed repair areas to receive compatible terrazzo repair material.\nInstall and compact the repair material to match the adjacent flooring elevation, color, and aggregate as closely as possible.\nGrind, hone, and polish the repaired sections to blend with the surrounding finish.',
   'Verify the repaired terrazzo is secure, level, and free of loose edges or immediate tripping hazards.\nVerify the repair color, aggregate, sheen, and transitions blend with the surrounding flooring as closely as possible.'),
  ('ceiling_tile', 'Acoustical ceiling', 'acoustical ceiling, ACT, ceiling tile, ceiling grid, drop ceiling, suspended ceiling, cielo acústico, cielo falso, losetas de cielo, grid', 'SF',
   '# Acoustical Ceiling Installation\nProvide and install {amount}acoustical ceiling tile and suspension grid system {where}.\nProvide compatible main runners, cross tees, perimeter molding, hanger wires, fasteners, and accessories as required.\nLay out and install the grid to provide consistent tile placement and alignment.\nCut and fit ceiling tiles neatly around lights, diffusers, sprinklers, access panels, and other fixed components.\nCoordinate ceiling elevations and penetrations with existing conditions.',
   'Verify the ceiling grid is level, properly aligned, securely suspended, and adequately supported.\nVerify ceiling tiles are seated correctly and free of broken edges, stains, or visible damage.\nVerify perimeter cuts and penetrations have a clean, uniform appearance.'),
  ('other', 'Access panel', 'access panel, access door, ceiling access, wall access, panel de acceso, puerta de acceso', 'EA',
   '# Access Panel Installation\nProvide and install {amount}access panel {where}.\nPrepare the opening to accommodate the approved panel dimensions and location.\nProvide framing, backing, blocking, anchors, fasteners, and reinforcement as required.\nSet, level, align, and securely fasten the access-panel frame.\nAdjust the panel door to provide clear access and proper operation.',
   'Verify the access panel is properly aligned, securely fastened, and stable.\nVerify the panel opens, closes, and latches as intended.\nVerify the perimeter transitions have a clean, finished appearance.'),
  ('other', 'Barn door', 'barn door, sliding barn door, rail door, track door, puerta corrediza, puerta de granero', 'EA',
   '# Barn Door & Rail Installation\nProvide and install {amount}barn door and rail system {where}.\nProvide the approved door, track, rollers, stops, guides, handles, fasteners, and associated hardware.\nProvide permanent wall backing, blocking, anchors, and reinforcement as required to support the rail system.\nLevel, align, and securely fasten the track to the supporting structure.\nHang and adjust the door to provide proper clearance and smooth operation.',
   'Verify the rail system is level, properly aligned, securely anchored, and adequately supported.\nVerify the door slides smoothly, remains properly guided, and stops securely at both ends.\nVerify the door, hardware, and surrounding transitions have a clean, finished appearance.'),
  ('other', 'Handrail', 'handrail, railing, guardrail, wall rail, grab rail, pasamanos, baranda, barandal', 'LF',
   '# Handrail Installation\nFabricate and install {amount}handrail {where}.\nProvide the approved material, profile, color, finish, posts, brackets, base plates, anchors, fasteners, and accessories.\nProvide blocking and reinforcement as required for secure attachment.\nSet, level, align, anchor, and securely fasten the handrail to sound supporting surfaces.\nSeal penetrations and touch up affected finishes as required.',
   'Verify the handrail is properly aligned, securely anchored, stable, and adequately supported.\nVerify posts, brackets, welds, connections, edges, and transitions have a clean, finished appearance.'),
  ('laminate', 'Cabinet relamination', 'relaminate, laminate repair, cabinet laminate, door laminate, reface cabinets, relaminar, reparar laminado, laminar gabinetes, forrar puertas', 'SF',
   '# Cabinet Repair & Relamination\nRepair and relaminate {amount}cabinet surfaces {where}.\nRemove loose, damaged, or deteriorated laminate as required.\nRepair serviceable doors, drawer fronts, panels, corners, edges, and cabinet components.\nPrepare the substrate to receive the approved replacement laminate.\nApply the laminate using compatible adhesive and provide clean seams, edges, corners, and terminations.\nAdjust doors, drawers, hinges, slides, and hardware for proper operation.',
   'Verify the laminate is fully adhered and free of bubbles, loose edges, chips, or exposed substrate.\nVerify repaired doors, drawers, hinges, slides, and hardware function as intended.\nVerify the color, pattern, edges, seams, and transitions have a consistent appearance.'),
  ('other', 'Countertop support', 'speed braces, countertop brackets, support brackets, counter support, escuadras, refuerzo de countertop', 'EA',
   '# Countertop Support Installation\nProvide and install {amount}countertop support bracket {where}.\nProvide compatible speed braces, blocking, backing, anchors, fasteners, and reinforcement as required.\nSecure the supports to sound wall framing or supporting structure.\nAlign and space the supports to provide proper countertop elevation and load distribution.\nSecure the countertop to the support system as required.',
   'Verify each support is properly positioned, securely anchored, and adequately reinforced.\nVerify the countertop is level, stable, securely fastened, and properly supported.')
ON DUPLICATE KEY UPDATE aliases = VALUES(aliases), unit = VALUES(unit), scope_text = VALUES(scope_text), checks = VALUES(checks), is_active = 1;
